(()=>{'use strict';
const P=window.GasPhysics,$=id=>document.getElementById(id),TAU=2*Math.PI,C=window.BookTheme.palette({gold:'#e4c389',cyan:'#7abdc4',muted:'#98aeae',line:'#293c45'}),key='galaxies-chapter-8-labs';
const defaults={M:4,T1:5,n1:-4,n:-3,T:6,alpha:-.5,z:6,compTau:1,hMass:12,eta:1,a:.8,dz:.1,nR:-4,age:.5,tAlpha:.5,eps:.01,tau:1,E:51,bn:-1,bt:20,L:38,wn:-1,wt:2},s={...defaults},bounds={M:[1,12],T1:[4.5,6],n1:[-5,-2],n:[-5,-2],T:[5,8],alpha:[-1,1],z:[0,15],compTau:[0,3],hMass:[11,14],eta:[.5,3],a:[-1.5,1.5],dz:[-.2,.2],nR:[-5,-3],age:[.01,3],tAlpha:[0,3],eps:[-.02,.02],tau:[0,2],E:[50,52],bn:[-2,0],bt:[1,100],L:[36,40],wn:[-3,0],wt:[.1,10]};
try{const v=JSON.parse(localStorage.getItem(key)||'{}');for(const k in bounds)if(Number.isFinite(v[k]))s[k]=Math.max(bounds[k][0],Math.min(bounds[k][1],v[k]));}catch{}
function save(){try{localStorage.setItem(key,JSON.stringify(s));}catch{}}
const ids={'shock-M':'M','shock-T':'T1','shock-n':'n1','radcool-n':'n','radcool-T':'T','radcool-alpha':'alpha','compton-z':'z','compton-tau':'compTau','hse-mass':'hMass','hse-eta':'eta','buoy-a':'a','buoy-z':'dz','cradius-n':'nR','cradius-age':'age','thermal-alpha':'tAlpha','thermal-eps':'eps','thermal-tau':'tau','blast-E':'E','blast-n':'bn','blast-time':'bt','wind-L':'L','wind-n':'wn','wind-time':'wt'};
for(const[id,k]of Object.entries(ids))$(id).value=s[k];
const fmt=(n,d=3)=>(Math.abs(n)<.5*10**(-d)?0:n).toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d}),sci=n=>n!==0&&(Math.abs(n)>=1000||Math.abs(n)<.001)?n.toExponential(2):fmt(n,3),set=(id,v)=>$(id).textContent=v,output=(id,v)=>set(id+'-value',v),motion=matchMedia('(prefers-reduced-motion: reduce)'),running=new Map(),labels={'shock-play':'播放稳态流','cradius-play':'推进诊断年龄','thermal-play':'观察线性扰动','blast-play':'播放相似扩张','wind-play':'播放持续注能'};
function stop(id){const r=running.get(id);if(r)cancelAnimationFrame(r.frame);running.delete(id);set(id,labels[id]);$(id).setAttribute('aria-pressed','false');save();}
function play(id,start,end,assign,render,duration=9000){if(running.has(id)){stop(id);return;}if(motion.matches){assign(end);render();save();return;}assign(start);render();const r={frame:0,last:0,start:performance.now()};running.set(id,r);set(id,'暂停示范');$(id).setAttribute('aria-pressed','true');const frame=now=>{if(motion.matches||document.hidden){stop(id);return;}const t=Math.min(1,(now-r.start)/duration);if(now-r.last>45||t===1){assign(start+(end-start)*t);render();r.last=now;}if(t<1)r.frame=requestAnimationFrame(frame);else stop(id);};r.frame=requestAnimationFrame(frame);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)[...running.keys()].forEach(stop);});motion.addEventListener('change',()=>{if(motion.matches)[...running.keys()].forEach(stop);});
const io=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)e.target.querySelectorAll('button[id$="-play"]').forEach(b=>{if(running.has(b.id))stop(b.id);});}));Object.keys(labels).forEach(id=>io.observe($(id).closest('.gas-lab')));
function bind(id,render,animation){$(id).addEventListener('input',e=>{if(animation)stop(animation);s[ids[id]]=+e.target.value;save();render();});}
function logTicks(domain){const lo=Math.ceil(Math.log10(domain[0])),hi=Math.floor(Math.log10(domain[1])),step=Math.max(1,Math.ceil((hi-lo)/4));return Array.from({length:Math.floor((hi-lo)/step)+1},(_,i)=>10**(lo+i*step));}
function canvas(id){const c=$(id),r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);c.width=Math.round(r.width*d);c.height=Math.round(r.height*d);const ctx=c.getContext('2d');ctx.setTransform(d,0,0,d,0,0);return {c,ctx,w:r.width,h:r.height};}
function plot(id,xd,yd,xt,yt,log=false){return window.BookCharts.frame(id+'-chart',{x:d3.scaleLinear().domain(xd),y:(log?d3.scaleLog():d3.scaleLinear()).domain(yd),xLabel:xt,yLabel:yt});}
function line(p,ds,fx,fy,color=C.gold,dash='',label){window.BookCharts.addSeries(p.node,ds.map(d=>({x:fx(d),y:fy(d)})),label);p.layer.append('path').datum(ds).attr('class','line').attr('d',d3.line().defined(d=>Number.isFinite(fy(d))).x(d=>p.x(fx(d))).y(d=>p.y(fy(d)))).attr('stroke',color).attr('stroke-dasharray',dash);}
function point(p,x,y,color=C.gold){p.layer.append('line').attr('x1',p.x(x)).attr('x2',p.x(x)).attr('y1',p.m.t).attr('y2',p.h-p.m.b).attr('stroke',C.muted).attr('stroke-dasharray','3 5');p.layer.append('circle').attr('cx',p.x(x)).attr('cy',p.y(y)).attr('r',3.5).attr('fill',color);}
const grid=(n,lo,hi)=>Array.from({length:n},(_,i)=>lo+(hi-lo)*i/(n-1));
let phase=0;
function shockScene(){const v=P.shock(s.M,10**s.T1,10**s.n1),{c,ctx,w,h}=canvas('shock-canvas'),mid=w/2,L=(w-38)/2,top=71,bottom=h-79;ctx.fillStyle=window.BookTheme.color('#0a1720');ctx.fillRect(18,top-10,L,bottom-top+25);ctx.fillStyle=window.BookTheme.color('#211f1a');ctx.fillRect(mid,top-10,L,bottom-top+25);ctx.strokeStyle=C.gold;ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(mid,top-18);ctx.lineTo(mid,bottom+25);ctx.stroke();const cycle=L*(1+v.compression),count=Math.ceil(cycle/23),spacing=cycle/count;for(let row=0;row<6;row++)for(let i=0;i<count;i++){const q=((i*spacing+phase*52+row*7)%cycle)-L,x=q<0?mid+q:mid+q/v.compression,y=top+(bottom-top)*row/5;ctx.fillStyle=q<0?C.cyan:C.gold;ctx.beginPath();ctx.arc(x,y,1.8,0,TAU);ctx.fill();}ctx.font='11px -apple-system,sans-serif';ctx.textAlign='center';ctx.fillStyle=C.cyan;ctx.fillText('上游',mid/2,20);ctx.fillText('T₁='+sci(v.T1)+' K',mid/2,39);ctx.fillStyle=C.gold;ctx.fillText('下游',mid+mid/2,20);ctx.fillText('T₂='+sci(v.T2)+' K',mid+mid/2,39);ctx.font='10px -apple-system,sans-serif';ctx.fillStyle=C.muted;ctx.fillText('v₁='+fmt(v.v1,1)+' km/s',mid/2,h-44);ctx.fillText('v₂='+fmt(v.v2,1)+' km/s',mid+mid/2,h-44);ctx.fillText('nH,₁='+v.nH1.toExponential(1),mid/2,h-27);ctx.fillText('nH,₂='+v.nH2.toExponential(1),mid+mid/2,h-27);ctx.fillText('激波静止参考系',mid,h-8);c.setAttribute('aria-label',`平面绝热跃迁，Mach${s.M}，上游${fmt(v.v1,1)}km/s、下游${fmt(v.v2,1)}km/s，密度比${fmt(v.compression)}，温度比${fmt(v.temperature)}。点列演示速度比，不表示真实秒尺度。`);}
function shock(){const v=P.shock(s.M,10**s.T1,10**s.n1),p=plot('shock',[1,12],[1,4.2],'上游 Mach 数','压缩比 ρ₂/ρ₁');line(p,grid(130,1,12).map(x=>({x,y:P.shock(x,1,1).compression})),d=>d.x,d=>d.y);line(p,[{x:1,y:4},{x:12,y:4}],d=>d.x,d=>d.y,C.cyan,'3 5');point(p,s.M,v.compression);shockScene();output('shock-M',fmt(s.M,1));output('shock-T',fmt(s.T1,2));output('shock-n',fmt(s.n1,1));set('shock-ratio',fmt(v.compression));set('shock-T2',sci(v.T2));set('shock-K',fmt(v.entropy));set('shock-result',`下游Mach=${fmt(v.M2)}，P₂/P₁=${fmt(v.pressure)}。${s.M===1?'这是无跃迁极限，密度、温度、熵代理都不变。':'质量通量nH v守恒；流动变慢，压力与熵代理增加。'} 青色横线是γ=5/3的强激波压缩比上限4。`);}
['shock-M','shock-T','shock-n'].forEach(id=>bind(id,shock,'shock-play'));$('shock-sonic').onclick=()=>{stop('shock-play');s.M=s.M===1?4:1;$('shock-M').value=s.M;save();shock();};$('shock-play').onclick=()=>play('shock-play',0,12,v=>{phase=v;},shockScene,12000);
function radcool(){const n=10**s.n,T=10**s.T,v=P.cooling(T,n,1e-22,s.alpha),data=grid(160,5,8).map(x=>({x,y:P.cooling(10**x,n,1e-22,s.alpha).time/P.Myr})),ys=data.map(v=>v.y).concat(v.tff/P.Myr),p=plot('radcool',[5,8],[10**Math.floor(Math.log10(Math.min(...ys))),10**Math.ceil(Math.log10(Math.max(...ys)))],'log₁₀ T / K','时标（Myr）',true);line(p,data,d=>d.x,d=>d.y);line(p,[{x:5,y:v.tff/P.Myr},{x:8,y:v.tff/P.Myr}],d=>d.x,d=>d.y,C.cyan,'4 5');point(p,s.T,v.time/P.Myr);output('radcool-n',fmt(s.n,1));output('radcool-T',fmt(s.T,2));output('radcool-alpha',fmt(s.alpha,2));set('radcool-time',sci(v.time/P.Myr));set('radcool-ff',sci(v.tff/P.Myr));set('radcool-ratio',sci(v.ratio));set('radcool-result',`当前指定Λ=${v.lambda.toExponential(2)} erg cm³/s，体积损失C=${v.loss.toExponential(2)} erg cm⁻³/s。${v.ratio<1?'辐射时标短于此均匀球tff，忽略冷却会有问题。':'辐射时标长于此均匀球tff，但不保证所有热源与流动都可忽略。'} 金线不是一团气体的降温轨迹。`);}
['radcool-n','radcool-T','radcool-alpha'].forEach(id=>bind(id,radcool));
function compton(){const v=P.compton(s.z,s.compTau),data=grid(180,0,15).map(x=>({x,...P.compton(x)})),p=plot('compton',[0,15],[.01,1e4],'背景红移 z','时标（Gyr）',true);line(p,data,d=>d.x,d=>d.time/P.Gyr);line(p,data,d=>d.x,d=>d.hubbleTime/P.Gyr,C.cyan,'4 5');point(p,s.z,v.time/P.Gyr);output('compton-z',fmt(s.z,1));output('compton-tau',fmt(s.compTau,2));set('compton-T',fmt(v.Tcmb,2));set('compton-time',sci(v.time/P.Gyr));set('compton-remain',fmt(v.remaining*100,1)+'%');set('compton-result',`金线tComp，青线1/H(z)。当前tComp/[1/H]=${fmt(v.time/v.hubbleTime)}；固定该背景经过${fmt(s.compTau,2)}个tComp，温度超额剩${fmt(v.remaining*100,1)}%。这是局部交换模型，不把长达多个哈勃时标的固定背景外推当作真实热史。`);}
bind('compton-z',compton);bind('compton-tau',compton);
function hse(){const M=10**s.hMass,v=P.nfwHSE(M,s.eta,1),data=grid(180,0,1).map(x=>({x,y:P.nfwHSE(M,s.eta,x).logRatio})),p=plot('hse',[0,1],[Math.floor(v.logRatio*1.05),0],'r / R₂₀₀c','log₁₀ (ρgas / ρ₀)');line(p,data,d=>d.x,d=>d.y);output('hse-mass',fmt(s.hMass,2));output('hse-eta',fmt(s.eta,2));set('hse-R',fmt(v.h.R,1));set('hse-T',sci(v.T));set('hse-edge',sci(v.ratio));set('hse-result',`T₂₀₀c=${sci(v.T200)} K，rₛ=${fmt(v.h.rs,1)} kpc，b=${fmt(v.b,2)}。归一化剖面中心ρ/ρ₀=1，外边界为${v.ratio.toExponential(2)}。固定η时换暗晕质量会改变物理尺寸和温度，归一化形状保持相同。`);}
bind('hse-mass',hse);bind('hse-eta',hse);
function buoyScene(v){const{c,ctx,w,h}=canvas('buoy-canvas'),cx=w*.43,zero=h*.53,scale=h*1.7,cy=zero-s.dz*scale;ctx.strokeStyle=C.line;ctx.lineWidth=1;for(let i=-2;i<=2;i++){const y=zero-i*.1*scale;ctx.beginPath();ctx.moveTo(24,y);ctx.lineTo(w-55,y);ctx.stroke();}ctx.setLineDash([4,5]);ctx.strokeStyle=C.muted;ctx.beginPath();ctx.arc(cx,zero,17,0,TAU);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=window.BookTheme.color('#e4c38925');ctx.strokeStyle=C.gold;ctx.beginPath();ctx.arc(cx,cy,18,0,TAU);ctx.fill();ctx.stroke();ctx.fillStyle=C.gold;ctx.font='11px sans-serif';ctx.textAlign='center';ctx.fillText('气团',cx,cy+4);const dir=Math.sign(v.acceleration),x=cx+35,start=cy,end=cy-dir*36;ctx.strokeStyle=C.gold;if(dir){ctx.beginPath();ctx.moveTo(x,start);ctx.lineTo(x,end);ctx.moveTo(x-4,end+dir*6);ctx.lineTo(x,end);ctx.lineTo(x+4,end+dir*6);ctx.stroke();}ctx.strokeStyle=C.cyan;ctx.beginPath();ctx.moveTo(w-28,55);ctx.lineTo(w-28,100);ctx.moveTo(w-32,94);ctx.lineTo(w-28,100);ctx.lineTo(w-24,94);ctx.stroke();ctx.fillStyle=C.cyan;ctx.fillText('重力',w-28,43);ctx.fillStyle=C.muted;ctx.font='10px sans-serif';ctx.fillText('虚线原位 · 金色箭头为浮力方向',w/2,h-12);c.setAttribute('aria-label',`熵梯度a=${s.a}，向上位移${s.dz}H，气团与环境密度比${fmt(v.densityRatio)}，向上浮力加速度${fmt(v.acceleration)}g。非时间演化轨迹。`);}
function buoy(){const v=P.buoyancy(s.a,s.dz),data=grid(140,-.2,.2).map(x=>({x,y:P.buoyancy(s.a,x).acceleration})),p=plot('buoy',[-.2,.2],[-.25,.25],'向上位移 Δz / H','向上浮力 \\(a_b/g\\)');line(p,data,d=>d.x,d=>d.y);line(p,[{x:-.2,y:0},{x:.2,y:0}],d=>d.x,d=>d.y,C.cyan,'3 5');point(p,s.dz,v.acceleration);buoyScene(v);output('buoy-a',fmt(s.a,2));output('buoy-z',fmt(s.dz,2));set('buoy-density',fmt(v.densityRatio));set('buoy-acc',fmt(v.acceleration));set('buoy-N',fmt(v.N2));set('buoy-result',`${s.a>0?'K随高度增加，浮力与位移相反，稳定恢复。':s.a<0?'K随高度降低，浮力放大位移，对流不稳定。':'K不随高度改变，这个理想模型为中性。'} Δz=${fmt(s.dz,2)}H，N²/(g/H)=${fmt(v.N2)}。图中箭头仅示意方向，不编码实际行程。`);}
bind('buoy-a',buoy);bind('buoy-z',buoy);
function radialScene(id,current,maxRadius,unit,caption){const{c,ctx,w,h}=canvas(id+'-canvas'),cx=w/2,cy=(h-33)/2,R=Math.min(w-65,h-75)/2,frac=current/maxRadius;ctx.strokeStyle=C.line;ctx.lineWidth=.8;for(const f of [.25,.5,.75,1]){ctx.beginPath();ctx.arc(cx,cy,R*f,0,TAU);ctx.stroke();}ctx.fillStyle=window.BookTheme.color('#e4c38914');ctx.strokeStyle=C.gold;ctx.lineWidth=1.4;ctx.beginPath();ctx.arc(cx,cy,R*frac,0,TAU);ctx.fill();ctx.stroke();ctx.fillStyle=C.gold;ctx.beginPath();ctx.arc(cx,cy,2.5,0,TAU);ctx.fill();ctx.font='11px sans-serif';ctx.textAlign='center';ctx.fillText(fmt(current,1)+' '+unit,cx,h-29);ctx.fillStyle=C.muted;ctx.font='10px sans-serif';ctx.fillText(caption,cx,h-10);c.setAttribute('aria-label',`${caption}；当前半径${fmt(current,1)}${unit}，外参照${fmt(maxRadius,1)}${unit}。同心圆不代表真实密度剖面。`);}
function cradius(){const nR=10**s.nR,v=P.coolingRadius(nR,s.age),data=grid(160,0,3).map(x=>({x,y:P.coolingRadius(nR,x).radius})),p=plot('cradius',[0,3],[0,210],'诊断年龄 t（Gyr）','rcool（kpc）');line(p,data,d=>d.x,d=>d.y);line(p,[{x:0,y:200},{x:3,y:200}],d=>d.x,d=>d.y,C.cyan,'3 5');point(p,s.age,v.radius);radialScene('cradius',v.radius,200,'kpc','初始剖面诊断 · 非物质轨迹');output('cradius-n',fmt(s.nR,1));output('cradius-age',fmt(s.age,2));set('cradius-r',fmt(v.radius,1));set('cradius-mass',fmt(v.fractionCooled*100,1)+'%');set('cradius-rate',sci(v.rate/P.Msun*P.yr));set('cradius-result',`初始Mgas=${(v.mass/P.Msun).toExponential(2)} M☉，外边界冷却时标tR=${fmt(v.outerTime/P.Gyr,2)}Gyr。${v.raw>=1?'诊断已到外边界，模型内初始质量均满足时标条件；不意味着真实气体供应停止。':'内部满足时标条件的初始质量份额与rcool/R相同。'} 这是另一套r⁻²气体剖面，未连接上方HSE解。`);}
['cradius-n','cradius-age'].forEach(id=>bind(id,cradius,'cradius-play'));$('cradius-play').onclick=()=>play('cradius-play',.01,3,v=>{s.age=Math.round(v*100)/100;$('cradius-age').value=s.age;},cradius);
function thermal(){const v=P.thermal(s.tAlpha,s.eps,s.tau),data=grid(180,.8,1.2).map(x=>({x,y:P.thermalNet(s.tAlpha,x)})),p=plot('thermal',[.8,1.2],[-.5,.5],'温度 θ=T/T₀','净冷却 ℓ / Γ');line(p,data,d=>d.x,d=>d.y);line(p,[{x:.8,y:0},{x:1.2,y:0}],d=>d.x,d=>d.y,C.cyan,'3 5');point(p,v.theta,v.net);output('thermal-alpha',fmt(s.tAlpha,2));output('thermal-eps',fmt(s.eps,3));output('thermal-tau',fmt(s.tau,2));set('thermal-growth',fmt(v.growth,2));set('thermal-delta',fmt(v.delta*100,2)+'%');set('thermal-net',fmt(v.net,3));set('thermal-result',`${s.tAlpha>1?'该加热律下α>1，小温度扰动线性衰减。':s.tAlpha<1?'该加热律下α<1，小温度扰动线性增长。':'α=1，本指定幂律在等压下净冷却恒为零。'} 当前θ=${fmt(v.theta,4)}；探针使用线性扰动解，曲线是指定净冷却函数，不是非线性时间轨迹。`);}
['thermal-alpha','thermal-eps','thermal-tau'].forEach(id=>bind(id,thermal,'thermal-play'));$('thermal-play').onclick=()=>play('thermal-play',0,2,v=>{s.tau=Math.round(v*20)/20;$('thermal-tau').value=s.tau;},thermal,6500);
function blast(){const E=10**s.E,n=10**s.bn,v=P.blast(E,n,s.bt),data=grid(160,1,100).map(x=>({x,y:P.blast(E,n,x).R/P.pc})),max=data[data.length-1].y,p=plot('blast',[0,100],[0,max*1.08],'爆炸年龄（kyr）','激波 R（pc）');line(p,data,d=>d.x,d=>d.y);point(p,s.bt,v.R/P.pc);radialScene('blast',v.R/P.pc,max,'pc','同一物理尺度 · 参照100kyr');output('blast-E',fmt(s.E,1));output('blast-n',fmt(s.bn,1));output('blast-time',fmt(s.bt,0));set('blast-R',fmt(v.R/P.pc,1));set('blast-v',sci(v.v/1e5));set('blast-mass',sci(v.swept/P.Msun));set('blast-result',`E=${E.toExponential(1)} erg保持不变，R∝t⁰·⁴，v∝t⁻⁰·⁶。当前扫过质量${sci(v.swept/P.Msun)} M☉；是否远大于抛射物、辐射是否可忽略，需要额外输入与检查，本解析外推没有自动保证这些条件。`);}
['blast-E','blast-n','blast-time'].forEach(id=>bind(id,blast,'blast-play'));$('blast-play').onclick=()=>play('blast-play',1,100,v=>{s.bt=Math.round(v);$('blast-time').value=s.bt;},blast);
function wind(){const L=10**s.L,n=10**s.wn,v=P.wind(L,n,s.wt),data=grid(160,.1,10).map(x=>({x,y:P.wind(L,n,x).R/P.pc})),p=plot('wind',[0,10],[0,data[data.length-1].y*1.08],'持续注能时间（Myr）','薄壳 R（pc）');line(p,data,d=>d.x,d=>d.y);point(p,s.wt,v.R/P.pc);output('wind-L',fmt(s.L,1));output('wind-n',fmt(s.wn,1));output('wind-time',fmt(s.wt,1));set('wind-R',fmt(v.R/P.pc,1));set('wind-v',sci(v.v/1e5));set('wind-energy',v.thermal.toExponential(2));set('wind-result',`已注入Lwt=${v.input.toExponential(2)} erg；热泡${v.thermal.toExponential(2)}、壳动能${v.kinetic.toExponential(2)}、壳层辐射${v.radiated.toExponential(2)} erg，相加等于注入。R∝t⁰·⁶的前提是持续恒功率，不能用于源停机后的演化。`);$('wind-budget').setAttribute('aria-label',`恒功率薄壳模型：热能45.45%，动能19.48%，壳层辐射35.06%；总注能${v.input.toExponential(2)}erg。`);}
$('wind-budget').innerHTML='<span style="width:45.454545%"></span><span style="width:19.480519%"></span><span style="width:35.064936%"></span>';['wind-L','wind-n','wind-time'].forEach(id=>bind(id,wind,'wind-play'));$('wind-play').onclick=()=>play('wind-play',.1,10,v=>{s.wt=Math.round(v*10)/10;$('wind-time').value=s.wt;},wind);
window.GasQuizzes.forEach(item=>{const row=document.createElement('article');row.className='quiz-item';const h=document.createElement('h3');h.textContent=item.q;const opts=document.createElement('div');opts.className='quiz-options';const feedback=document.createElement('p');feedback.className='quiz-feedback';feedback.setAttribute('aria-live','polite');item.options.forEach((text,i)=>{const b=document.createElement('button');b.textContent=text;b.setAttribute('aria-pressed','false');b.onclick=()=>{opts.querySelectorAll('button').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));feedback.textContent=(i===item.answer?'正确。':'再想一步。')+item.why;};opts.append(b);});row.append(h,opts,feedback);$('gas-quiz').append(row);});
function tutor(text){window.showTutor('我在学习Mo, van den Bosch & White (2010)第8章。'+text+' 请核算公式、成分和单位，逐步解释物理机制，明确教材依据、额外教学近似与不可由本模型推出的结论。');}
$('tutor-open').onclick=()=>tutor('依据§8.1–8.8 pp.366–416，串联激波、冷却、静水平衡、稳定性和反馈。网页9个实验使用独立背景；气体采用完全电离纯氢、γ=5/3、μ=.5，不是一套统一流体模拟。');
$('shock-question').onclick=()=>tutor(`§8.3.1 pp.376–379；完全电离纯氢γ=5/3,μ=.5，上游Mach=${s.M},T1=10^${s.T1}K,nH1=10^${s.n1}cm^-3。请推导χ、P/T跃迁、下游Mach与K2/K1，检查三条跃迁守恒，不把点列当作真实流体模拟。`);
$('radcool-question').onclick=()=>tutor(`§8.1.3和§8.4.1 pp.367–370、385–387；纯氢n=2nH,nH=10^${s.n}cm^-3,T=10^${s.T}K,Λ=1e-22(T/1e6K)^α,α=${s.alpha}。总密度rhoTot=mp nH/.15。请核算等容tcool与均匀球tff，说明这与等压焓时标及真实金属冷却表的区别。`);
$('compton-question').onclick=()=>tutor(`§8.1.2 p367；完全电离纯氢，电子质子同温、非相对论，z=${s.z},Tγ=2.725(1+z)K,t/tComp=${s.compTau}，背景固定。请推导温度超额指数衰减与密度抵消，区别局部tComp、1/H(z)和宇宙年龄。`);
$('hse-question').onclick=()=>tutor(`§8.2.1 p373式8.29–8.30；z0 NFW M200c=10^${s.hMass}Msun,c200c=8,H0=70,纯氢μ=.5,η=T/T200c=${s.eta}，忽略气体自引力，仅归一化密度。请从dP/dr=-rho GM(<r)/r²推导指数剖面与中心极限，解释相同η下的质量相似缩放。`);
$('buoy-question').onclick=()=>tutor(`§8.2.2 pp.373–374；向上z，Kenv=K0 exp(az/H),a=${s.a},Δz/H=${s.dz},γ=5/3；气团绝热保K0且与新位置环境等压。请推导密度比、浮力加速度及N²，检查恢复方向，不把局部模型当成非线性对流模拟。`);
$('cradius-question').onclick=()=>tutor(`§8.4.2 pp.387–389；独立初始r^-2纯氢气体，R200kpc,T1e6K,Λ1e-22,nH(R)=10^${s.nR}cm^-3,诊断年龄${s.age}Gyr。请推导tR、rcool、初始满足质量份额及其变化率，说明边界截断与中心奇异；它不是上方HSE剖面或真实成星率。`);
$('thermal-question').onclick=()=>tutor(`§8.5.1 pp.393–396；新增等压模型，恒定每氢核加热Γ，Λ∝T^α,α=${s.tAlpha},初始δθ=${s.eps},τ=${s.tau}。净损失/Γ=θ^(α-1)-1，探针用线性δθ=epsilon exp[(1-alpha)τ]。请推导阈值与时间归一化5kT0/Γ，解释为何不能推广到任意加热律或多相介质。`);
$('blast-question').onclick=()=>tutor(`§8.6.1 pp.399–403；均匀纯氢nH=10^${s.bn}cm^-3，瞬时E=10^${s.E}erg，年龄${s.bt}kyr，γ=5/3，R=1.15(E/rho)^1/5 t^2/5。请核算R、v、扫过质量，列出Sedov阶段与辐射、抛射物质量的限制。`);
$('wind-question').onclick=()=>tutor(`§8.6.2–8.6.3 pp.404–407式8.207；恒功率Lw=10^${s.L}erg/s，均匀纯氢nH=10^${s.wn}cm^-3，t=${s.wt}Myr。热泡绝热、外壳薄且可辐射。请核算R、v、热能5/11、动能15/77、辐射27/77的能量账，区别全绝热爆炸及源停机。`);
function renderAll(){shock();radcool();compton();hse();buoy();cradius();thermal();blast();wind();}let timer;window.addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(renderAll,140);});renderAll();
})();
